.sc-tw .material-symbols-outlined{font-family:'Material Symbols Outlined';font-weight:normal;font-style:normal;line-height:1;letter-spacing:normal;text-transform:none;display:inline-block;white-space:nowrap;word-wrap:normal;direction:ltr;-webkit-font-feature-settings:'liga';font-feature-settings:'liga';-webkit-font-smoothing:antialiased;}
.sc-tw .custom-logo{max-height:2.4rem;width:auto;height:auto;display:inline-block;vertical-align:middle;}
.admin-bar .sc-tw nav.fixed,.admin-bar .sc-tw nav.sticky,.admin-bar .sc-tw header.fixed,.admin-bar .sc-tw header.sticky{top:32px !important;}
@media screen and (max-width:782px){.admin-bar .sc-tw nav.fixed,.admin-bar .sc-tw nav.sticky,.admin-bar .sc-tw header.fixed,.admin-bar .sc-tw header.sticky{top:46px !important;}}
.sc-mirror{padding-top:0 !important;padding-bottom:0 !important;}
.sc-mirror .fw-container{max-width:none !important;width:100% !important;padding-left:0 !important;padding-right:0 !important;}
.sc-mirror .fw-row{margin-left:0 !important;margin-right:0 !important;}
.sc-mirror .fw-row > .fw-col-12{padding-left:0 !important;padding-right:0 !important;}
/* ---- reproduced Tailwind CSS (offline) ---- */
.sc-tw{font-family:'Inter',system-ui,-apple-system,sans-serif;}
.sc-tw *,.sc-tw ::before,.sc-tw ::after{box-sizing:border-box;border-width:0;border-style:solid;border-color:#e5e7eb}
.sc-tw ::before,.sc-tw ::after{--tw-content:''}
.sc-tw h1,.sc-tw h2,.sc-tw h3,.sc-tw h4,.sc-tw h5,.sc-tw h6{font-size:inherit;font-weight:inherit;margin:0}
.sc-tw p,.sc-tw blockquote,.sc-tw figure,.sc-tw pre,.sc-tw dl,.sc-tw dd{margin:0}
.sc-tw a{color:inherit;text-decoration:inherit}
.sc-tw b,.sc-tw strong{font-weight:bolder}
.sc-tw ul,.sc-tw ol,.sc-tw menu{list-style:none;margin:0;padding:0}
.sc-tw button,.sc-tw input,.sc-tw select,.sc-tw textarea{font-family:inherit;font-size:100%;font-weight:inherit;line-height:inherit;color:inherit;margin:0;padding:0}
.sc-tw button,.sc-tw [role=button]{cursor:pointer;background-color:transparent;background-image:none}
.sc-tw img,.sc-tw svg,.sc-tw video,.sc-tw canvas,.sc-tw audio,.sc-tw iframe,.sc-tw embed,.sc-tw object{display:block;vertical-align:middle}
.sc-tw img,.sc-tw video{max-width:100%;height:auto}
.sc-tw .flex{display:flex !important}
.sc-tw .flex-col{flex-direction:column !important}
.sc-tw .justify-between{justify-content:space-between !important}
.sc-tw .gap-6{gap:1.5rem !important}
.sc-tw .mb-16{margin-bottom:4rem !important}
.sc-tw .space-y-3 > :not([hidden]) ~ :not([hidden]){margin-top:0.75rem !important;margin-bottom:0 !important}
.sc-tw .text-xs{font-size:0.75rem !important;line-height:1rem !important}
.sc-tw .font-bold{font-weight:700 !important}
.sc-tw .tracking-widest{letter-spacing:0.1em !important}
.sc-tw .text-blue-400{--tw-text-opacity:1 !important;color:rgb(96 165 250 / var(--tw-text-opacity, 1)) !important}
.sc-tw .uppercase{text-transform:uppercase !important}
.sc-tw .text-3xl{font-size:1.875rem !important;line-height:2.25rem !important}
.sc-tw .text-white{--tw-text-opacity:1 !important;color:rgb(255 255 255 / var(--tw-text-opacity, 1)) !important}
.sc-tw .tracking-tight{letter-spacing:-0.025em !important}
.sc-tw .items-center{align-items:center !important}
.sc-tw .gap-3{gap:0.75rem !important}
.sc-tw .bg-white\/5{background-color:rgb(255 255 255 / 0.05) !important}
.sc-tw .border{border-width:1px !important}
.sc-tw .border-white\/10{border-color:rgb(255 255 255 / 0.1) !important}
.sc-tw .px-4{padding-left:1rem !important;padding-right:1rem !important}
.sc-tw .py-2{padding-top:0.5rem !important;padding-bottom:0.5rem !important}
.sc-tw .rounded-full{border-radius:9999px !important}
.sc-tw .backdrop-blur-sm{backdrop-filter:blur(4px) !important;-webkit-backdrop-filter:blur(4px) !important}
.sc-tw .text-amber-400{--tw-text-opacity:1 !important;color:rgb(251 191 36 / var(--tw-text-opacity, 1)) !important}
.sc-tw .w-4{width:1rem !important}
.sc-tw .h-4{height:1rem !important}
.sc-tw .font-semibold{font-weight:600 !important}
.sc-tw .text-slate-200{--tw-text-opacity:1 !important;color:rgb(226 232 240 / var(--tw-text-opacity, 1)) !important}
@media (min-width:640px){.sc-tw .sm\:flex-row{flex-direction:row !important}.sc-tw .sm\:items-end{align-items:flex-end !important}.sc-tw .sm\:text-4xl{font-size:2.25rem !important;line-height:2.5rem !important}}
@media (min-width:1024px){.sc-tw .lg\:text-5xl{font-size:3rem !important;line-height:1 !important}}
